"use client";

import { CloseCircle, Logout, Menu, SearchNormal1, User } from "iconsax-react";
import { useEffect, useState } from "react";
import { Link } from "@/lib/navigation";
const logo = "/assets/logo/logo-01-01.png";
import useLogin from "../hooks/auth/useLogin";
import useAuthStore from "../store/useAuthStore";
import SearchInput from "./SearchInput";

function Navbar() {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const { LogOut, isLoggingOut } = useLogin();
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
  const defaultDashboardRoute = useAuthStore(
    (state) => state.defaultDashboardRoute,
  );

  const role = useAuthStore((state) => state.role);
  const isSuperAdmin = role === "super_admin";
  const isAdmin = role === "admin";
  const isUser = role === "user";

  const closeSidebar = () => setIsSidebarOpen(false);
  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);
  const toggleSearch = () => setIsSearchOpen(!isSearchOpen);

  const handleLogout = async () => {
    try {
      await LogOut();
      closeSidebar();
    } catch (error) {
      void error;
    }
  };

  useEffect(() => {
    if (isSidebarOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isSidebarOpen]);

  return (
    <>
      <header className="sticky top-0 z-50 bg-white/95 backdrop-blur-md border-b border-gray-200 shadow-sm">
        <div className="max-w-7xl w-full mx-auto flex justify-center items-center">
          <div className="w-full justify-between px-3 sm:px-4 md:px-6 py-2.5 md:py-3 flex items-center gap-2 sm:gap-3 md:gap-4">
            <button
              onClick={toggleSidebar}
              className="md:hidden p-2 rounded-[10px] hover:bg-gray-100 active:bg-gray-200 transition-colors text-slate-900 touch-manipulation"
              aria-label="منو"
            >
              <Menu size={20} color="currentColor" />
            </button>
            <Link
              to="/"
              onClick={closeSidebar}
              className="flex items-center gap-2"
            >
              <img
                src={logo}
                alt="اربعین تی وی"
                className="h-8 sm:h-9 md:h-10 w-auto"
              />
            </Link>
            <div className="hidden md:block flex-1 max-w-2xl mx-8">
              <SearchInput className="no-focus-visible md:hidden p-2 rounded-[10px] hover:bg-gray-100 text-slate-900 touch-manipulation" />
            </div>
            <button
              onClick={toggleSearch}
              className="no-focus-visible md:hidden p-2 rounded-[10px] hover:bg-gray-100 text-slate-900 touch-manipulation"
              aria-label="جستجو"
            >
              <SearchNormal1 size={20} color="currentColor" />
            </button>
            <div className="hidden md:flex items-center gap-3 ">
              {isAuthenticated ? (
                <>
                  <Link
                    to={
                      isSuperAdmin
                        ? "/dashboard/upload"
                        : isUser
                          ? "/user-dashboard?action=create-channel"
                          : "/dashboard/user-upload"
                    }
                    className="h-10 px-4 rounded-[10px] border border-gray-300 bg-white hover:bg-gray-50 active:bg-gray-100 text-sm font-medium flex items-center gap-2 text-slate-900 transition-colors shadow-sm hover:shadow"
                  >
                    بارگذاری ویدیو
                  </Link>

                  <Link
                    to={defaultDashboardRoute}
                    className="h-10 px-4 rounded-[10px] border border-gray-300 bg-white hover:bg-gray-50 active:bg-gray-100 text-sm font-medium flex items-center gap-2 text-slate-900 transition-colors shadow-sm hover:shadow"
                  >
                    مدیریت کانال‌ها
                  </Link>

                  {/* <button
                    onClick={handleLogout}
                    disabled={isLoggingOut}
                    className="h-10 px-4 rounded-[10px] border border-red-300 bg-white hover:bg-red-50 active:bg-red-100 text-sm font-medium flex items-center gap-2 text-red-600 transition-colors shadow-sm hover:shadow disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    <Logout size={18} color="currentColor" />
                    {isLoggingOut ? "در حال خروج..." : "خروج"}
                  </button> */}
                </>
              ) : (
                <Link
                  to="/login"
                  className="h-10 px-4 rounded-[10px] border border-gray-300 bg-white hover:bg-gray-50 active:bg-gray-100 text-sm font-medium flex items-center gap-2 text-slate-900 transition-colors shadow-sm hover:shadow"
                >
                  <User size={18} color="currentColor" />
                  <span className="text-[16px]">ورود</span>
                </Link>
              )}
            </div>
          </div>
        </div>

        {isSearchOpen && (
          <div className="md:hidden px-3 sm:px-4 pb-3">
            <SearchInput />
          </div>
        )}
      </header>

      {isSidebarOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-[60] md:hidden animate-in fade-in duration-300"
          onClick={closeSidebar}
        />
      )}

      <aside
        className={`fixed top-0 right-0 h-dvh w-80 max-w-[85vw] bg-white shadow-2xl z-[70] transform transition-transform duration-300 ease-in-out md:hidden ${
          isSidebarOpen ? "translate-x-0" : "translate-x-full"
        }`}
      >
        <div className="flex flex-col h-full">
          <div className="flex shrink-0 items-center justify-between p-4 border-b border-gray-200">
            <h2 className="text-xl font-extrabold bg-gradient-to-r from-orange-500 to-orange-600 bg-clip-text text-transparent">
              منو
            </h2>
            <button
              onClick={closeSidebar}
              className="p-2 rounded-[10px] hover:bg-gray-100 active:bg-gray-200 transition-colors touch-manipulation"
              aria-label="بستن منو"
            >
              <CloseCircle size={24} color="currentColor" />
            </button>
          </div>

          <div className="min-h-0 flex-1 overflow-y-auto">
            <nav className="p-4 space-y-2">
              <Link
                to="/"
                onClick={closeSidebar}
                className="flex items-center gap-3 p-3 rounded-[10px] hover:bg-gray-100 active:bg-gray-200 transition-colors text-gray-900 font-medium"
              >
                <span>خانه</span>
              </Link>
              {isAuthenticated && (
                <Link
                  to={defaultDashboardRoute}
                  onClick={closeSidebar}
                  className="flex items-center gap-3 p-3 rounded-[10px] hover:bg-gray-100 active:bg-gray-200 transition-colors text-gray-900 font-medium"
                >
                  <span>مدیریت کانال‌ها</span>
                </Link>
              )}
              {isAuthenticated && (
                <Link
                  to={
                    isSuperAdmin
                      ? "/dashboard/upload"
                      : isUser
                        ? "/user-dashboard?action=create-channel"
                        : "/dashboard/user-upload"
                  }
                  onClick={closeSidebar}
                  className="flex items-center gap-3 p-3 rounded-[10px] hover:bg-gray-100 active:bg-gray-200 transition-colors text-gray-900 font-medium"
                >
                  <span>بارگذاری ویدیو</span>
                </Link>
              )}
            </nav>

            <div className="border-t border-gray-200 p-4 space-y-2" />
          </div>

          <div className="shrink-0 border-t border-gray-200 p-4 pb-[max(1rem,env(safe-area-inset-bottom))]">
            {isAuthenticated ? (
              <button
                onClick={handleLogout}
                disabled={isLoggingOut}
                className="w-full h-12 rounded-[10px] bg-gradient-to-r from-red-600 to-red-700 hover:from-red-700 hover:to-red-800 active:scale-[0.98] text-white font-medium flex items-center justify-center gap-2 transition-all duration-200 shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Logout size={20} color="#ffffff" />
                {isLoggingOut ? "در حال خروج..." : "خروج از حساب کاربری"}
              </button>
            ) : (
              <Link
                to="/login"
                onClick={closeSidebar}
                className="w-full h-12 rounded-[10px] bg-gradient-to-r from-orange-500 to-orange-600 hover:from-blue-700 hover:to-purple-700 active:scale-[0.98] text-white font-medium flex items-center justify-center gap-2 transition-all duration-200 shadow-lg"
              >
                <User size={20} color="#ffffff" />
                ورود به حساب کاربری
              </Link>
            )}
          </div>
        </div>
      </aside>
    </>
  );
}

export default Navbar;

import { useState } from "react";
import { toast } from "react-toastify";

import useChannel from "../../hooks/channel/useChannel";
import useChannelDetail from "../../hooks/channel/useChannelDetail";

import { Camera } from "iconsax-react";
import ImageCropModal from "./ImageCropModal";
import ProfileSettings from "./ProfileSettings";

function ChannelSettings({ channelId }) {
  const { data, refetch } = useChannelDetail();

  const {
    changeChannelImage,
    changeProfileChannelImage,
    isChangingChannelImage,
    isChangingProfileImage,
  } = useChannel(1, 10, {}, { enabled: false });

  const [cropImage, setCropImage] = useState(null);
  const [cropType, setCropType] = useState(null);
  const [isDirty, setIsDirty] = useState(false);

  const isLoading = isChangingChannelImage || isChangingProfileImage;

  const openCropper = (file, type) => {
    if (!file) {
      const input = document.createElement("input");
      input.type = "file";
      input.accept = "image/*";

      input.onchange = (e) => {
        const selectedFile = e.target.files[0];
        if (!selectedFile) return;
        openCropper(selectedFile, type);
      };

      input.click();
      return;
    }

    if (!["image/jpeg", "image/png"].includes(file.type)) {
      toast.error("فقط JPG و PNG مجاز است");
      return;
    }

    if (type === "cover") {
      if (file.size > 4 * 1024 * 1024) {
        toast.error("حداکثر حجم ۴ مگابایت");
        return;
      }
    }

    setCropImage(URL.createObjectURL(file));
    setCropType(type);
  };

  return (
    <div className="space-y-8">
      {/* PREVIEW */}
      <div className="mb-16 rounded-[10px]">
        <div className="mt-6 relative ">
          {/* COVER */}
          <div className="aspect-[7/1] rounded-[10px] overflow-hidden relative group">
            <img
              src={data?.data?.background_image}
              className="w-full h-full object-cover"
            />

            <div
              onClick={() => openCropper(null, "cover")}
              className="absolute inset-0 flex items-center justify-center bg-black/0 group-hover:bg-black/40 transition cursor-pointer"
            >
              <Camera size={34} color="#fff" />
            </div>
          </div>

          {/* PROFILE */}
          <div className="absolute bottom-[-40px] right-8 group">
            <div className="relative w-16 h-16 sm:w-24 sm:h-24 rounded-[10px] overflow-hidden border-4 border-white shadow-lg">
              <img
                src={data?.data?.image}
                className="w-full h-full object-cover"
              />

              <div
                onClick={() => openCropper(null, "profile")}
                className="absolute inset-0 flex items-center justify-center bg-black/0 group-hover:bg-black/40 transition cursor-pointer"
              >
                <Camera size={28} color="#fff" />
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* PROFILE SETTINGS */}
      <ProfileSettings setIsDirty={setIsDirty} />

      {/* CROPPER */}
      <ImageCropModal
        isOpen={!!cropImage}
        image={cropImage}
        aspect={cropType === "cover" ? 7 / 1 : 1}
        title={cropType === "cover" ? "برش کاور" : "برش تصویر پروفایل"}
        onClose={() => {
          setCropImage(null);
          setCropType(null);
        }}
        onSave={(file) => {
          if (cropType === "cover") {
            changeProfileChannelImage(file, channelId, {
              onSuccess: () => {
                toast.success("کاور بروزرسانی شد");
                refetch();
              },
              onError: () => {
                toast.error("خطا در بروزرسانی کاور");
              },
            });
          }

          if (cropType === "profile") {
            changeChannelImage(file, channelId, {
              onSuccess: () => {
                toast.success("پروفایل بروزرسانی شد");
                refetch();
              },
              onError: () => {
                toast.error("خطا در بروزرسانی پروفایل");
              },
            });
          }

          setCropImage(null);
          setCropType(null);
        }}
      />
    </div>
  );
}

export default ChannelSettings;

import { Image } from "iconsax-react";
import { useEffect, useRef, useState } from "react";
import FramePickerModal from "./FramePickerModal";
import { Button } from "../../ui";

export default function CoverPicker({
  value, // current cover File or null
  onChange, // (file) => void
  defaultCovers = [], // array of URLs (e.g., ['/covers/d1.png', ...])
  videoFile = null,
  videoUrl = null,
}) {
  const [thumbDrag, setThumbDrag] = useState(false);
  const [showDefaultModal, setShowDefaultModal] = useState(false);
  const [showFrameModal, setShowFrameModal] = useState(false);
  const [previewUrl, setPreviewUrl] = useState(null);
  const prevUrlRef = useRef(null);

  // build preview when value changes
  useEffect(() => {
    if (!value) {
      if (prevUrlRef.current) {
        try {
          URL.revokeObjectURL(prevUrlRef.current);
        } catch (e) {}
        prevUrlRef.current = null;
      }
      setPreviewUrl(null);
      return;
    }

    if (typeof value === "string") {
      // string URL
      setPreviewUrl(value);
      return;
    }

    // File or Blob
    const u = URL.createObjectURL(value);
    if (prevUrlRef.current) {
      try {
        URL.revokeObjectURL(prevUrlRef.current);
      } catch (e) {}
    }
    prevUrlRef.current = u;
    setPreviewUrl(u);

    return () => {
      if (prevUrlRef.current) {
        try {
          URL.revokeObjectURL(prevUrlRef.current);
        } catch (e) {}
        prevUrlRef.current = null;
      }
    };
  }, [value]);

  useEffect(() => {
    return () => {
      if (prevUrlRef.current) {
        try {
          URL.revokeObjectURL(prevUrlRef.current);
        } catch (e) {}
      }
    };
  }, []);

  const onFileInputChange = (e) => {
    const f = e.target.files?.[0];
    if (f) onChange(f);
  };

  return (
    <div>
      <div
        className={`rounded-[10px] border-2 transition-all ${thumbDrag ? "border-blue-500 bg-blue-50" : "border-dashed border-gray-300 hover:border-gray-400"} p-6 mt-5 flex flex-col items-center justify-center text-center cursor-pointer min-h-[250px]`}
        onDragOver={(e) => {
          e.preventDefault();
          setThumbDrag(true);
        }}
        onDragLeave={() => setThumbDrag(false)}
        onDrop={(e) => {
          e.preventDefault();
          setThumbDrag(false);
          const f = e.dataTransfer.files?.[0];
          if (f && f.type.startsWith("image/")) onChange(f);
        }}
      >
        <input
          id="thumb-input"
          type="file"
          accept="image/*"
          className="sr-only"
          onChange={onFileInputChange}
        />
        {previewUrl ? (
          <div className="w-full space-y-2">
            <div className="relative w-full max-w-md mx-auto">
              <img
                className="w-full h-48 rounded-lg object-cover border border-gray-200"
                src={previewUrl}
                alt="Thumbnail"
              />
            </div>
            <div className="flex items-center justify-between">
              <p className="text-sm text-gray-700 font-medium truncate">
                {value?.name ?? "کاور انتخابی"}
              </p>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onChange(null);
                }}
                className="text-red-500 hover:text-red-700 text-sm"
              >
                حذف
              </button>
            </div>
          </div>
        ) : (
          <label
            htmlFor="thumb-input"
            className="flex flex-col items-center gap-3 cursor-pointer"
          >
            <div className="w-16 h-16 rounded-full bg-purple-100 flex items-center justify-center">
              <Image
                size={32}
                color="currentColor"
                className="text-purple-600"
              />
            </div>
            <div>
              <p className="text-sm font-medium text-gray-900">
                برای انتخاب تصویر کلیک کنید
              </p>
              <p className="text-xs text-gray-500 mt-1">
                یا تصویر را اینجا بکشید و رها کنید
              </p>
            </div>
          </label>
        )}
      </div>
      <label className="block text-sm font-semibold text-gray-900 mt-4">
        <div>تصویر شاخص</div>
      </label>
      <div className="flex gap-3 mt-6">
        <Button
          type="button"
          variant="secondary"
          onClick={() => document.getElementById("thumb-input")?.click()}
          className="flex-1"
        >
          انتخاب تصویر کاور
        </Button>
        <Button
          variant="secondary"
          onClick={() => setShowFrameModal(true)}
          className="flex-1"
        >
          انتخاب کاور از فریم ویدیو
        </Button>
      </div>

      {/* <DefaultCoversModal
        open={showDefaultModal}
        onClose={() => setShowDefaultModal(false)}
        defaultCovers={defaultCovers}
        onSelect={(file) => onChange(file)}
      /> */}

      <FramePickerModal
        open={showFrameModal}
        onClose={() => setShowFrameModal(false)}
        videoFile={videoFile}
        videoUrl={videoUrl}
        onSelect={(file) => onChange(file)}
      />
    </div>
  );
}

import { ScanBarcode } from "iconsax-react";
import { useCallback, useEffect, useRef, useState } from "react";

export default function FramePickerModal({
  open,
  onClose,
  videoFile,
  onSelect,
}) {
  const videoRef = useRef(null);
  const [videoSrc, setVideoSrc] = useState(null);
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [loadingFrames, setLoadingFrames] = useState(false);
  const [playing, setPlaying] = useState(false);
  const [suggested, setSuggested] = useState([]);

  // 🎬 ساخت src از فایل
  useEffect(() => {
    if (!open || !videoFile) return;
    const src = URL.createObjectURL(videoFile);
    setVideoSrc(src);
    return () => {
      URL.revokeObjectURL(src);
      suggested.forEach((s) => URL.revokeObjectURL(s.url));
      setSuggested([]);
    };
  }, [open, videoFile]);

  // ▶️ کنترل پخش
  const togglePlay = () => {
    const v = videoRef.current;
    if (!v) return;
    if (v.paused) {
      v.play().catch(() => setPlaying(false));
    } else {
      v.pause();
    }
  };

  // ⏱️ گرفتن فریم از زمان خاص
  const captureAt = (time) => {
    const video = videoRef.current;
    return new Promise((resolve) => {
      const handler = () => {
        const canvas = document.createElement("canvas");
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(video, 0, 0);
        canvas.toBlob(
          (blob) => {
            const file = new File([blob], `frame-${time}.jpg`, {
              type: "image/jpeg",
            });
            resolve({
              url: URL.createObjectURL(blob),
              file,
              time,
            });
          },
          "image/jpeg",
          0.9,
        );
        video.removeEventListener("seeked", handler);
      };
      video.addEventListener("seeked", handler);
      video.currentTime = time;
    });
  };

  // ✨ تولید فریم‌ها
  const generateFrames = useCallback(async () => {
    const video = videoRef.current;
    if (!video?.duration) return;

    setLoadingFrames(true);

    const positions = [0.2, 0.4, 0.6, 0.8]; // 👉 4 تا فریم
    const frames = [];

    for (let p of positions) {
      const time = video.duration * p;
      try {
        const frame = await captureAt(time);
        frames.push(frame);
      } catch (e) {}
    }

    setSuggested(frames);
    setLoadingFrames(false);
  }, []);

  // 📦 بعد از لود ویدیو
  const handleLoadedMetadata = () => {
    const v = videoRef.current;
    if (!v) return;
    setDuration(v.duration || 0);
    generateFrames();
  };

  // 📸 گرفتن فریم فعلی
  const captureCurrentFrame = async () => {
    const v = videoRef.current;
    const canvas = document.createElement("canvas");
    canvas.width = v.videoWidth;
    canvas.height = v.videoHeight;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(v, 0, 0);
    return new Promise((resolve) => {
      canvas.toBlob((blob) => {
        const file = new File([blob], "frame.jpg", {
          type: "image/jpeg",
        });
        resolve(file);
      });
    });
  };

  if (!open || !videoFile) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
      <div className="bg-white rounded-2xl w-full h-auto sm:max-w-xl overflow-hidden shadow-2xl relative max-h-[90vh] flex flex-col">
        {/* HEADER */}
        <div className="flex justify-end items-center px-4 sm:px-6 py-3 sm:py-4 shrink-0">
          <button className="text-xl px-2" onClick={onClose}>
            ✕
          </button>
        </div>

        <div className="px-4 sm:px-6 pb-6 space-y-5 overflow-y-auto">
          {/* 🎬 VIDEO */}
          <div className="bg-[#24364A] rounded-xl overflow-hidden relative shrink-0">
            <video
              ref={videoRef}
              src={videoSrc}
              controls
              onLoadedMetadata={handleLoadedMetadata}
              onTimeUpdate={(e) => setCurrentTime(e.target.currentTime)}
              onPlay={() => setPlaying(true)}
              onPause={() => setPlaying(false)}
              onEnded={() => setPlaying(false)}
              className="frame-picker-video w-full h-[220px] sm:h-[300px] object-contain"
              playsInline
              crossOrigin="anonymous"
            />
          </div>

          <button
            type="button"
            onClick={togglePlay}
            className="inline-flex min-h-11 items-center gap-2 rounded-lg px-3 text-sm text-slate-700 hover:bg-slate-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-500"
          >
            <svg
              viewBox="0 0 24 24"
              fill="currentColor"
              className="h-5 w-5"
              aria-hidden="true"
            >
              {playing ? (
                <path d="M6 4h4v16H6zm8 0h4v16h-4z" />
              ) : (
                <path d="M8 5v14l11-7z" />
              )}
            </svg>
            <span>{playing ? "توقف ویدیو" : "پخش ویدیو"}</span>
          </button>

          <div className="flex flex-col gap-4">
            <p className="text-sm text-gray-600">
              برای انتخاب تصویر شاخص می توانیدحین پخش ویدیو ،تصویر دلخواه خود را
              برش بزنید.
            </p>
            {/* 📸 انتخاب فریم فعلی */}
            <div className="flex justify-center items-center">
              <button
                onClick={async () => {
                  const file = await captureCurrentFrame();
                  onSelect(file);
                  onClose();
                }}
                className="bg-gray-100 hover:bg-gray-200 p-3 sm:p-4 rounded-3xl text-sm sm:text-base w-full sm:w-auto"
              >
                <div className="flex gap-2 justify-center">
                  <ScanBarcode size={24} color="currentColor" />
                  <span>انتخاب فریم فعلی ({Math.floor(currentTime)}s)</span>
                </div>
              </button>
            </div>
          </div>

          {/* ✨ فریم‌های پیشنهادی */}
          <div>
            {suggested.length > 0 && (
              <p className="text-sm text-gray-600 mb-3">
                لطفا از بین تصاویر یکی را انتخاب کنید:
              </p>
            )}
            {loadingFrames ? (
              <div className="flex flex-col items-center justify-center py-10 text-gray-500">
                <div className="w-10 h-10 border-4 border-gray-300 border-t-gray-700 rounded-full animate-spin"></div>
                <p className="mt-3 text-sm">در حال استخراج فریم‌ها...</p>
              </div>
            ) : (
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-2 sm:gap-3">
                {suggested.map((item, index) => (
                  <div
                    key={index}
                    onClick={() => {
                      onSelect(item.file);
                      onClose();
                    }}
                    className="cursor-pointer rounded-lg overflow-hidden active:scale-95 sm:hover:scale-105 transition"
                  >
                    <img
                      src={item.url}
                      className="w-full h-24 object-cover"
                      alt={`frame-${index}`}
                    />
                  </div>
                ))}
              </div>
            )}
          </div>
          <p className="text-sm text-gray-600">
            (برای تصویر شاخص حتما یک عکس جذاب ، واضح، با کیفیت و مرتب با ویدیو
            انتخاب کنید )
          </p>
        </div>
      </div>
    </div>
  );
}

