import { CloseCircle, SearchNormal1, ArrowDown2 } from "iconsax-react";
import { useMemo, useRef, useState, useEffect } from "react";

function MultiSelect({
  options = [],
  value = [],
  onChange,
  placeholder = "انتخاب کنید",
  emptyMessage = "موردی پیدا نشد",
  disabled = false,
  getOptionLabel,
}) {
  const [query, setQuery] = useState("");
  const [isOpen, setIsOpen] = useState(false);
  const wrapperRef = useRef(null);

  const selectedValues = Array.isArray(value)
    ? value.map((item) => String(item))
    : value
      ? [String(value)]
      : [];

  const resolveLabel = (item) => {
    if (typeof getOptionLabel === "function") {
      return getOptionLabel(item);
    }

    return item?.name || item?.title || `آیتم ${item?.id}`;
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const filteredOptions = useMemo(() => {
    if (!query.trim()) return options;

    return options.filter((item) =>
      resolveLabel(item).toLowerCase().includes(query.trim().toLowerCase()),
    );
  }, [options, query, resolveLabel]);

  const selectedItems = useMemo(
    () => options.filter((item) => selectedValues.includes(String(item.id))),
    [options, selectedValues],
  );

  const handleToggle = (optionId) => {
    const optionKey = String(optionId);

    const next = selectedValues.includes(optionKey)
      ? selectedValues.filter((item) => item !== optionKey)
      : [...selectedValues, optionKey];

    onChange?.(next);
  };

  return (
    <div className="relative" ref={wrapperRef}>
      {/* Select Box */}
      <button
        type="button"
        disabled={disabled}
        onClick={() => setIsOpen((prev) => !prev)}
className={[
  "flex h-11 w-full items-center gap-4 rounded-[10px] px-4 text-sm bg-white border transition",
  isOpen ? "border-blue-500" : "border-gray-200",
].join(" ")}      >
        <ArrowDown2
          size={14}
          color="currentColor"
          className={`transition ${isOpen ? "rotate-180" : ""}`}
        />
        <span className="truncate">
          {selectedItems.length > 0
            ? `${selectedItems.length} پلی‌لیست انتخاب شده`
            : placeholder}
        </span>
      </button>

      {/* Dropdown */}
      {isOpen && (
        <div className="absolute z-50 mt-2 w-full rounded-lg border border-gray-200 bg-white shadow-lg">
          {/* Search */}
          <div className="relative p-2">
            <SearchNormal1
              color="currentColor"
              size={18}
              className="absolute right-5 top-1/2 -translate-y-1/2"
            />

            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="جستجوی پلی‌لیست..."
              className="h-10 w-full rounded-lg border border-gray-300 px-4 pr-10 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {/* Selected */}
          {selectedItems.length > 0 && (
            <div className="flex flex-wrap gap-2 px-2 pb-2">
              {selectedItems.map((item) => (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => handleToggle(item.id)}
                  className="inline-flex items-center gap-1 rounded-full bg-blue-50 px-2 py-1 text-xs text-blue-700"
                >
                  {resolveLabel(item)}
                  <CloseCircle size={14} color="currentColor" />
                </button>
              ))}
            </div>
          )}

          {/* Options */}
          <div className="max-h-60 overflow-y-auto border-t">
            {filteredOptions.length === 0 ? (
              <p className="p-3 text-sm text-gray-500">{emptyMessage}</p>
            ) : (
              filteredOptions.map((item) => (
                <label
                  key={item.id}
                  className="flex cursor-pointer items-center gap-2 p-3 hover:bg-gray-50"
                >
                  <input
                    type="checkbox"
                    checked={selectedValues.includes(String(item.id))}
                    onChange={() => handleToggle(item.id)}
                  />

                  <span className="text-sm">{resolveLabel(item)}</span>
                </label>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default MultiSelect;

import Dropzone from "dropzone";
import { CloseCircle, DocumentUpload, TickCircle } from "iconsax-react";
import { useEffect, useRef, useState } from "react";
import axiosInstanceNew from "../utils/axiosConfigNew";
import { readAuthSession } from "../utils/auth";
const logoUpload = "/assets/logo/logo-upload.png";

Dropzone.autoDiscover = false;

function VideoDropzone({
  onUploaded,
  onProgress,
  onFileSelected,
  disabled = false,
}) {
  const dropzoneRef = useRef(null);
  const dzRef = useRef(null);
  const fileInputRef = useRef(null);

  const onUploadedRef = useRef(onUploaded);
  const onProgressRef = useRef(onProgress);
  const onFileSelectedRef = useRef(onFileSelected);

  const currentFileRef = useRef(null);

  const [progress, setProgress] = useState(0);
  const [isDragActive, setIsDragActive] = useState(false);
  const [uploadedFileName, setUploadedFileName] = useState("");
  const [errorMessage, setErrorMessage] = useState("");
  const [previewUrl, setPreviewUrl] = useState("");
  const previewRef = useRef(null);
  const isUploading = progress > 0;

  useEffect(() => {
    onUploadedRef.current = onUploaded;
  }, [onUploaded]);
  useEffect(() => {
    onProgressRef.current = onProgress;
  }, [onProgress]);
  useEffect(() => {
    onFileSelectedRef.current = onFileSelected;
  }, [onFileSelected]);

  useEffect(() => {
    const dz = new Dropzone(dropzoneRef.current, {
      url: `${axiosInstanceNew.defaults.baseURL.replace(/\/$/, "")}/video/upload`,
      method: "post",
      chunking: true,
      forceChunking: true,
      chunkSize: 5 * 1024 * 1024,
      maxFilesize: 2048, // in MB (2GB)
      retryChunks: true,
      retryChunksLimit: 3,
      maxFiles: 1,
      acceptedFiles: "video/*",
      previewTemplate: '<div style="display:none"></div>',
      headers: {
        Authorization: axiosInstanceNew.defaults.headers.common.Authorization,
      },
      autoProcessQueue: true, // ✅ خودکار آپلود می‌شود
      clickable: true,
      init: function () {
        dzRef.current = this;

        this.on("addedfile", (file) => {
          currentFileRef.current = file;

          if (disabled) {
            this.removeFile(file);
            return;
          }

          if (previewRef.current) {
            try {
              URL.revokeObjectURL(previewRef.current);
            } catch (e) {}
            previewRef.current = null;
          }

          const url = URL.createObjectURL(file);
          previewRef.current = url;
          setPreviewUrl(url);

          setUploadedFileName(file.name);
          setErrorMessage("");
          setProgress(0);

          if (onFileSelectedRef.current) {
            onFileSelectedRef.current(file);
          }
        });

        this.on("dragenter", () => setIsDragActive(true));
        this.on("dragleave", () => setIsDragActive(false));
        this.on("drop", () => setIsDragActive(false));

        this.on("sending", (file, xhr, formData) => {
          const extension = file.name.split(".").pop();
          formData.append("fileName", file.name);
          formData.append("extension", extension);
          formData.append("mimeType", file.type);

          const { token } = readAuthSession();
          if (token) {
            xhr.setRequestHeader("Authorization", `Bearer ${token}`);
          }
        });

        this.on("uploadprogress", (_, percent) => {
          setProgress(percent);
          if (onProgressRef.current) onProgressRef.current(percent);
        });

        this.on("success", (_, response) => {
          setProgress(100);
          const tempPath =
            response?.temp_path ?? response?.data?.temp_path ?? response;
          if (onUploadedRef.current) {
            try {
              onUploadedRef.current({
                temp_path: tempPath,
                file: currentFileRef.current,
              });
            } catch (e) {
              onUploadedRef.current(tempPath);
            }
          }
        });

        this.on("maxfilesexceeded", (file) => {
          this.removeAllFiles();
          this.addFile(file);
        });

        this.on("error", (_, err) => {
          setProgress(0);
          setErrorMessage(
            typeof err === "string"
              ? err
              : "آپلود فایل با خطا مواجه شد. لطفاً دوباره تلاش کنید.",
          );
          currentFileRef.current = null;

          if (previewRef.current) {
            try {
              URL.revokeObjectURL(previewRef.current);
            } catch (e) {}
            previewRef.current = null;
            setPreviewUrl("");
          }
        });
      },
    });

    return () => {
      try {
        dz.destroy();
      } catch (e) {}
      dzRef.current = null;
      currentFileRef.current = null;
      if (previewRef.current) {
        try {
          URL.revokeObjectURL(previewRef.current);
        } catch (e) {}
        previewRef.current = null;
      }
    };
  }, []);

  // وقتی کاربر از طریق input فایل انتخاب کرد
  const handleFileSelected = (e) => {
    if (disabled) return;

    const file = e.target.files && e.target.files[0];
    if (!file) return;

    // اضافه کردن فایل به Dropzone (خودکار آپلود می‌شود)
    if (dzRef.current) {
      // اگر قبلاً فایلی بود حذف می‌کنیم
      dzRef.current.removeAllFiles();
      dzRef.current.addFile(file);
    } else {
      // Fallback: فقط preview و state
      currentFileRef.current = file;
      if (previewRef.current) {
        try {
          URL.revokeObjectURL(previewRef.current);
        } catch (e) {}
        previewRef.current = null;
      }
      const url = URL.createObjectURL(file);
      previewRef.current = url;
      setPreviewUrl(url);
      setUploadedFileName(file.name);
      setErrorMessage("");
      setProgress(0);
    }

    // پاک کردن مقدار input
    e.target.value = "";
  };

  const handleCancelUpload = () => {
    if (dzRef.current) {
      dzRef.current.removeAllFiles();
      setUploadedFileName("");
      setProgress(0);
    }
    currentFileRef.current = null;
    if (previewRef.current) {
      try {
        URL.revokeObjectURL(previewRef.current);
      } catch (e) {}
      previewRef.current = null;
      setPreviewUrl("");
    }
  };

  const hasFile = !!uploadedFileName;

  return (
    <div className="space-y-3 mt-4">
      {isUploading ? (
        <div
          className={`rounded-xl border-2 p-6 sm:p-8 text-center min-h-[180px] flex items-center justify-center transition-all
  ${
    disabled
      ? "opacity-50 cursor-not-allowed bg-gray-100 border-gray-200"
      : isDragActive
        ? "border-orange-500 bg-orange-50"
        : "border-dashed border-gray-300 hover:border-orange-400 bg-gray-50/40"
  }
  ${hasFile ? "p-4" : ""}
`}
        >
          <div className="w-full max-w-full">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium text-gray-700">
                پیشرفت آپلود :
              </span>
              <span className="text-sm font-semibold text-blue-600">
                {Math.round(progress)}%
              </span>
            </div>

            <div className="w-full bg-gray-200 rounded-full h-2.5 overflow-hidden mb-3">
              <div
                className="bg-gradient-to-r to-blue-500 via-sky-500 from-blue-500 h-2.5 rounded-full transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>

            <p className="text-xs text-gray-500">
              {progress === 100
                ? "آپلود با موفقیت انجام شد!"
                : "لطفاً تا اتمام آپلود صبر کنید"}
            </p>
          </div>
        </div>
      ) : (
        <div
          ref={dropzoneRef}
          onClick={() => {
            if (disabled) return;
            if (fileInputRef.current) {
              fileInputRef.current.click();
            }
          }}
          className={`rounded-xl border-2 p-6 sm:p-8 text-center min-h-[180px] flex items-center justify-center transition-all ${
            isDragActive
              ? "border-orange-500 bg-orange-50"
              : "border-dashed border-gray-300 hover:border-orange-400 bg-gray-50/40"
          } ${hasFile ? "p-4" : ""}`}
        >
          <div className="space-y-3 w-full">
            {!hasFile ? (
              <>
                <div className="w-48 h-16 rounded-full  flex items-center justify-center mx-auto my-10">
                  <img src={logoUpload} alt="" />
                  {/* <div>{logoUpload}</div> */}
                  {/* <DocumentUpload size={32} className="text-orange-600" color="#F97316" /> */}
                </div>
                <div>
                  <p className="text-2xl font-semibold text-gray-900 mb-2">
                    بارگذاری ویدیو
                  </p>
                  <p className="text-sm font-semibold text-gray-900 mb-2">
                    برای انتخاب فایل ویدیو از دکمه پایین استفاده کنید
                  </p>
                  <p className="text-xs text-gray-500 mt-1">
                    یا فایل را اینجا بکشید و رها کنید
                  </p>
                </div>
                <div className="flex justify-center">
                  <div className="relative">
                    <button
                      type="button"
                      className="px-4 py-2 bg-white border border-gray-300 rounded-md text-sm hover:bg-orange-50 hover:border-orange-300 hover:text-orange-700 relative z-0"
                    >
                      انتخاب فایل ویدیو
                    </button>
                    <input
                      ref={fileInputRef}
                      type="file"
                      accept="video/*"
                      disabled={disabled}
                      onClick={(e) => e.stopPropagation()}
                      onChange={handleFileSelected}
                      style={{
                        position: "absolute",
                        top: 0,
                        left: 0,
                        width: "100%",
                        height: "100%",
                        opacity: 0,
                        cursor: "pointer",
                      }}
                    />
                  </div>
                </div>
              </>
            ) : (
              <div className="text-center w-full">
                {previewUrl ? (
                  <div className="mx-auto max-w-full mb-4">
                    <video
                      src={previewUrl}
                      controls
                      playsInline
                      className="mx-auto rounded-lg bg-black max-h-[420px] w-full object-contain"
                    />
                    <p className="text-xs text-gray-700 mt-2 bg-white border border-gray-200 rounded-full px-3 py-1 inline-flex items-center gap-1 mx-auto max-w-[220px]">
                      <TickCircle
                        size={14}
                        color="#D97706"
                      />
                      <span className="truncate">{uploadedFileName}</span>
                    </p>
                  </div>
                ) : (
                  <p className="text-xs text-gray-700 bg-white border border-gray-200 rounded-full px-3 py-1 inline-flex items-center gap-1 mx-auto max-w-[220px]">
                    <TickCircle
                      size={14}
                      color="#D97706"
                    />
                    <span className="truncate">{uploadedFileName}</span>
                  </p>
                )}
                <button
                  onClick={handleCancelUpload}
                  className="px-4 py-2.5 border border-gray-300 text-gray-700 font-medium rounded-lg hover:bg-gray-50 transition-all duration-200 text-sm flex items-center gap-1 mx-auto hover:border-orange-300 hover:text-orange-700"
                >
                  <CloseCircle size={16} color="currentColor" />
                  انصراف
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* {progress > 0 && progress < 100 && (
        <div>
          <div className="flex items-center justify-between mb-1">
            <span className="text-xs font-medium text-gray-600">پیشرفت آپلود</span>
            <span className="text-xs font-semibold text-orange-600">{Math.round(progress)}%</span>
          </div>
          <div className="w-full bg-gray-200 rounded-full h-2.5 overflow-hidden">
            <div
              className="bg-gradient-to-r from-orange-500 via-amber-500 to-yellow-500 h-2.5 rounded-full transition-all duration-300"
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>
      )} */}

      {!!errorMessage && (
        <div className="rounded-lg border border-red-200 bg-red-50 text-red-700 px-3 py-2 text-xs flex items-center gap-2">
          <CloseCircle size={14} color="#fb2c36" />
          <span>{errorMessage}</span>
        </div>
      )}
    </div>
  );
}

export default VideoDropzone;

import { Edit2, Eye, Trash } from "iconsax-react";
import { Button } from "../ui";

function VideoCard({ item, onDelete, onShow, onEdit, isDeleting, isEditing }) {
  const coverImage =
    item.cover_link ||
    item.cover_url ||
    item.cover ||
    item.thumbnailUrl ||
    "https://picsum.photos/seed/default/300/180";

  const channelName = item.channel_name || item.channelName || "";
  const title = item.title || String(item.id);
  const viewCount = item.view_count ?? item.views ?? 0;

  const isPublic = item.public_show === 1 || item.public_show === true;

  return (
    <div className="flex flex-col justify-between w-full sm:w-[315px] rounded-[10px] border border-gray-200 bg-white shadow-sm hover:shadow-md transition-all overflow-hidden mb-2">
      {/* تصویر */}
      <div className="relative w-full h-44 bg-gray-200">
        <img
          onClick={() => onShow(item.id)}
          src={coverImage}
          alt={title}
          className="w-full h-full object-cover"
          onError={(e) => {
            e.target.src = "https://picsum.photos/seed/default/300/180";
          }}
        />
        {/* <div className="absolute bottom-3 right-3 sm:bottom-4 sm:right-4 bg-white/95 backdrop-blur-xl px-3 sm:px-4 py-1.5 sm:py-2 rounded-2xl shadow-lg shadow-black/10 border border-white/50 flex items-center gap-1.5 text-xs sm:text-sm font-semibold text-slate-800">
          <Eye size={14} sm={16} color='#0f172a' className="text-indigo-500 flex-shrink-0" />
          <span>{viewCount}</span>
        </div> */}

        {/* وضعیت public/private */}
        <span
          className={`absolute top-2 right-2 px-2 py-1 text-xs rounded-full font-medium ${
            isPublic ? "bg-green-100 text-green-700" : "bg-red-100 text-red-600"
          }`}
        >
          {isPublic ? "عمومی" : "خصوصی"}
        </span>
      </div>

      {/* محتوا */}
      <div className="p-4 space-y-2">
        <p className="text-sm font-semibold text-gray-900 line-clamp-2">
          {title}
        </p>

        {/* {channelName && (
          <p className="text-xs text-gray-600 truncate flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-gray-400"></span>
            {channelName}
          </p>
        )} */}

        <p className="text-xs text-gray-500 flex items-center gap-1">
          <Eye size={14} color="#4a5565" />
          {Number(viewCount || 0).toLocaleString("fa-IR")} بازدید
        </p>
      </div>

      {/* دکمه‌ها */}
      <div className="flex items-center justify-between gap-2 p-3 border-t border-gray-100">
        {onEdit && (
          <Button
            onClick={() => onEdit(item)}
            disabled={isDeleting || isEditing}
            variant="outline"
            className="w-full"
          >
            <Edit2 className="w-4 h-4 sm:w-5 sm:h-5" color="#1D4ED8" />{" "}
            <span className="hidden sm:inline">ویرایش</span>{" "}
          </Button>
        )}

        {/* <button
          onClick={() => onShow(item.id)}
          disabled={isDeleting || isEditing}
          className="flex-1 h-10 rounded-lg border border-gray-300 hover:bg-gray-50 text-gray-700 text-xs font-medium flex items-center justify-center gap-2"
        >
          <Play className="w-5 h-5 sm:w-6 sm:h-6" color="black" /> <span className="hidden sm:inline">نمایش</span>        </button> */}

        <Button
          onClick={() => onDelete(item.id)}
          disabled={isDeleting}
          variant="dangeroutline"
          className="w-full"
        >
          <Trash
            className="w-4 h-4 sm:w-5 sm:h-5 "
            color="currentColor"
          />
          <span className="hidden sm:inline">حذف</span>
        </Button>
      </div>
    </div>
  );
}

export default VideoCard;

"use client";

import { Edit2, FolderAdd, TickCircle, Trash, User } from "iconsax-react";
import { useState } from "react";
import { toast } from "react-toastify";
import PaginationComponent from "../components/PaginationComponent";
import useChannel from "../hooks/channel/useChannel";
import { usePaginationParams } from "../hooks/ui/usePaginationParams";
import { Button, ConfirmModal } from "../ui";
import DashboardLayout from "../layouts/DashboardLayout";

function Channels() {
  const { page, setPage } = usePaginationParams(1);
  const {
    channels,
    pagination,
    createChannel,
    updateChannel,
    deleteChannel,
    isLoadingChannels,
    changeChannelImage,
  } = useChannel(page);

  const [name, setName] = useState("");
  const [username, setUsername] = useState("");
  const [imageFile, setImageFile] = useState(null);
  const [editing, setEditing] = useState(null);
  const [deleteConfirmId, setDeleteConfirmId] = useState(null);
  const [thumbDrag, setThumbDrag] = useState(false);

  const handleSubmit = async () => {
    if (!name.trim()) return;

    try {
      if (editing) {
        if (!imageFile && !editing?.image) {
          toast.error("لطفاً تصویر کانال را انتخاب کنید");
          return;
        }

        await updateChannel(editing.id, {
          name,
          slug: username // ✅ اضافه کن
        });
        if (imageFile) {
          await changeChannelImage(imageFile, editing.id);
        }

        toast.success("تغییرات کانال با موفقیت ذخیره شد");
        setEditing(null);
      } else {
        if (!imageFile) {
          toast.error("تصویر کانال الزامی است");
          return;
        }

        await createChannel({
          name,
          slug: username,
          image: imageFile,
        });


        // toast.success("کانال جدید با موفقیت ایجاد شد");
      }

      setName("");
      setUsername("");
      setImageFile(null);
    } catch {
      toast.error("خطا در انجام عملیات، دوباره تلاش کنید");
    }
  };

  const handleCancel = () => {
    setEditing(null);
    setName("");
    setImageFile(null);
  };

  const handleEdit = (c) => {
    setEditing(c);
    setName(c.name);
    setUsername(c.username || "");
    setImageFile(null);
  };

  const handleDelete = async () => {
    try {
      await deleteChannel(deleteConfirmId);
      toast.success("کانال با موفقیت حذف شد");
      setDeleteConfirmId(null);

    } catch {
      toast.error("حذف کانال موفقیت‌آمیز نبود");
    }
  };



  const totalPages = Number(pagination?.totalPages || 1);

  const handleChangeImage = async (id, file) => {
    try {
      await changeChannelImage(file, id);
      toast.success("تصویر کانال با موفقیت بروزرسانی شد");
    } catch {
      toast.error("آپلود تصویر انجام نشد");
    }
  };


  return (
    <DashboardLayout>
      <div className="space-y-6">

        {/* فرم ایجاد / ویرایش */}
        <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
          <h2 className="text-lg font-bold text-gray-900 mb-4">
            {editing ? "ویرایش کانال" : "ایجاد کانال جدید"}
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-start">
            {/* آپلود تصویر */}
            <div>
              <div
                className={`rounded-xl border-2 transition-all ${thumbDrag
                  ? "border-blue-500 bg-blue-50"
                  : "border-dashed border-gray-300 hover:border-gray-400"
                  } p-4 flex flex-col items-center justify-center text-center cursor-pointer min-h-[190px]`}
                onDragOver={(e) => {
                  e.preventDefault();
                  setThumbDrag(true);
                }}
                onDragLeave={() => setThumbDrag(false)}
                onDrop={(e) => {
                  e.preventDefault();
                  setThumbDrag(false);
                  const f = e.dataTransfer.files?.[0];
                  if (f && f.type.startsWith("image/")) setImageFile(f);
                }}
              >
                <input
                  id="channel-image-input"
                  type="file"
                  accept="image/*"
                  className="sr-only"
                  onChange={(e) =>
                    setImageFile(e.target.files?.[0] || null)
                  }
                />

                {imageFile ? (
                  <div className="w-full space-y-2">
                    <img
                      className="w-full h-32 rounded-lg object-cover border border-gray-200"
                      src={URL.createObjectURL(imageFile)}
                      alt="preview"
                    />
                    <div className="flex items-center justify-between">
                      <p className="text-xs text-gray-600 truncate">
                        {imageFile.name}
                      </p>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setImageFile(null);
                        }}
                        className="text-red-500 hover:text-red-700 text-xs"
                      >
                        حذف
                      </button>
                    </div>
                  </div>
                ) : editing?.image ? (
                  <label
                    htmlFor="channel-image-input"
                    className="flex flex-col items-center gap-2 cursor-pointer"
                  >
                    <img
                      src={
                        editing.image.startsWith("http")
                          ? editing.image
                          : `http://${editing.image}`
                      }
                      className="w-full h-32 rounded-lg object-cover border"
                    />
                    <p className="text-xs text-gray-600">
                      برای تغییر تصویر کلیک کنید
                    </p>
                  </label>
                ) : (
                  <label
                    htmlFor="channel-image-input"
                    className="flex flex-col items-center gap-2 cursor-pointer"
                  >
                    <div className="w-14 h-14 rounded-full bg-purple-100 flex items-center justify-center">
                      📷
                    </div>
                    <p className="text-sm font-medium text-gray-900">
                      برای انتخاب تصویر کلیک کنید
                    </p>
                    <p className="text-xs text-gray-500">
                      یا تصویر را اینجا رها کنید
                    </p>
                  </label>
                )}
              </div>
            </div>

            {/* نام کانال + دکمه‌ها */}
            <div className="md:col-span-2 space-y-3">
              <input
                value={name}
                onChange={(e) => setName(e.target.value)}
                onKeyPress={(e) => e.key === "Enter" && handleSubmit()}
                placeholder="نام کانال را وارد کنید"
                className="w-full h-11 px-4 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500"
              />

              <label className="space-y-2">
                {/* <span className="text-sm font-semibold text-gray-900">نام کاربری</span> */}
                <div className="relative">
                  <User size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input
                    value={username}
                    onChange={(e) => {
                      const value = e.target.value.toLowerCase();
                      const regex = /^[a-z0-9_]*$/;

                      if (regex.test(value)) {
                        setUsername(value);
                      }
                    }}
                    className="h-11 w-full rounded-lg border border-gray-300 pr-4 pl-10 focus:outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder="نام کاربری : مثلاً ali_m123"
                  />
                </div>
                <p className="text-xs text-gray-500 m-4">فقط حروف کوچک انگلیسی، اعداد و _ مجاز است.</p>
              </label>

              <div className="flex items-center gap-2">
                {editing && (
                  <Button
                    variant="secondary"
                    onClick={handleCancel}
                  >
                    انصراف
                  </Button>
                )}

                <Button
                  onClick={handleSubmit}
                  disabled={
                    !name.trim() ||
                    !username.trim() ||
                    (!editing && !imageFile) ||
                    (editing && !imageFile && !editing?.image)
                  }
                  className="w-full"
                  icon={editing ? <TickCircle size={18} /> : <FolderAdd size={18} />}
                >
                  {editing ? 'ذخیره تغییرات' : 'افزودن کانال'}
                </Button>
              </div>
            </div>
          </div>
        </div>

        {/* <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
          <h2 className="text-lg font-bold text-gray-900 mb-4">جستجوی کانال‌ها</h2>
          <div className="grid grid-cols-1 md:grid-cols-[1fr_auto] gap-3">
            <input
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              placeholder="نام کانال را وارد کنید"
              className="h-11 px-4 rounded-lg border border-gray-300 w-full focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              onClick={handleSearch}
              disabled={searchMutation.isPending}
              className="h-11 px-5 rounded-lg border border-gray-300 bg-white hover:bg-gray-50 disabled:bg-gray-100 disabled:cursor-not-allowed text-sm font-semibold inline-flex items-center justify-center gap-2"
            >
              <SearchNormal1 size={18} />
              {searchMutation.isPending ? 'در حال جستجو...' : 'جستجو'}
            </button>
          </div>
        </div> */}

        {/* لیست کانال‌ها */}
        <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
          <h2 className="text-lg font-bold text-gray-900 mb-4">
            لیست کانال‌ها
          </h2>

          {isLoadingChannels ? (
            <div className="space-y-3">
              {[1, 2, 3].map((i) => (
                <div key={i} className="h-16 bg-gray-100 rounded-lg animate-pulse" />
              ))}
            </div>
          ) : !channels?.length ? (
            <div className="text-center py-12">
              <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-4">
                <FolderAdd size={32} className="text-gray-400" />
              </div>
              <p className="text-sm text-gray-500">هنوز کانالی ایجاد نشده است</p>
            </div>
          ) : (
            <div className="space-y-3">
              {channels.map((c) => (
                <div
                  key={c.id}
                  className="flex flex-col sm:flex-row sm:items-center justify-between p-3 sm:p-4 rounded-lg border border-gray-200 bg-gray-50 hover:bg-gray-100 transition-colors"
                >
                  {/* محتوای چپ (تصویر + اطلاعات) */}
                  <div className="flex items-center gap-3 w-full sm:w-auto mb-3 sm:mb-0">
                    {c.image ? (
                      <img
                        src={
                          c.image.startsWith("http")
                            ? c.image
                            : `http://${c.image}`
                        }
                        alt={c.name}
                        className="w-20 h-20 sm:w-12 sm:h-12 rounded-lg object-cover border border-gray-200 flex-shrink-0"
                      />
                    ) : (
                      <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-lg bg-red-100 text-red-600 flex items-center justify-center text-xs font-medium flex-shrink-0">
                        بدون تصویر
                      </div>
                    )}

                    <div className="min-w-0 flex-1">
                      <span className="text-sm sm:text-base font-semibold text-gray-900 block line-clamp-1">
                        {c.name}
                      </span>

                      <span className="block text-xs text-gray-500 mt-1">
                        @{c.username}
                      </span>

                      <span className="block text-xs text-gray-400 mt-1">
                        ایجاد: {new Date(c.created_at).toLocaleDateString("fa-IR")} |
                        ویرایش: {new Date(c.updated_at).toLocaleDateString("fa-IR")}
                      </span>
                    </div>
                  </div>

                  {/* input مخفی برای آپلود تصویر - روی دکمه قرار می‌گیرد */}
                  <input
                    id={`chan-img-${c.id}`}
                    type="file"
                    accept="image/*"
                    className="sr-only"
                    onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) {
                        handleChangeImage(c.id, f);
                        e.target.value = "";
                      }
                    }}
                  />

                  {/* دکمه‌های اکشن */}
                  <div className="flex items-center gap-2 w-full sm:w-auto justify-end">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => handleEdit(c)}
                      icon={<Edit2 size={16} color="currentColor" />}
                      className="flex-1 sm:flex-none"
                    >
                      ویرایش
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => setDeleteConfirmId(c.id)}
                      icon={<Trash size={16} color="currentColor" />}
                      className="text-red-600 border-red-100 hover:bg-red-50 hover:text-red-700 flex-1 sm:flex-none"
                    >
                      حذف
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}

          <PaginationComponent
            totalPages={totalPages}
            currentPage={page}
            onPageChange={setPage}
            totalItems={pagination?.totalItems}
          />
        </div>
      </div>

      <ConfirmModal
        isOpen={!!deleteConfirmId}
        onClose={() => setDeleteConfirmId(null)}
        onConfirm={handleDelete}
        title="حذف کانال"
        message={`آیا از حذف کانال "${channels?.find((c) => c.id === deleteConfirmId)?.name || ""
          }" مطمئن هستید؟ این عمل قابل بازگشت نیست.`}
        confirmText="حذف"
        cancelText="انصراف"
        variant="danger"
      />
    </DashboardLayout>
  );
}

export default Channels;

"use client";

import { Sms, Lock, Eye, EyeSlash, Key, User } from "iconsax-react";
import { useState, useEffect } from "react";
import { Formik, Form, Field, ErrorMessage } from "formik";
import * as Yup from "yup";
const logo = "/assets/logo/logo-login.png";
import useLogin from "../hooks/auth/useLogin";
import useSendOtp from "../hooks/auth/useSendOtp";
import useCheckOtp from "../hooks/auth/useCheckOtp";
import useCompleteUserData from "../hooks/auth/useCompleteUserData";
import OTPInput from "../components/OTPInput";

const MODES = {
  LOGIN: 'LOGIN',
  REGISTER: 'REGISTER'
};

const STEPS = {
  PHONE: 'PHONE',
  OTP: 'OTP',
  COMPLETE: 'COMPLETE'
};

function Login() {
  const [mode, setMode] = useState(MODES.LOGIN);
  const [step, setStep] = useState(STEPS.PHONE);
  const [phoneNumber, setPhoneNumber] = useState("");
  const [userId, setUserId] = useState(null);
  const [authToken, setAuthToken] = useState(null);
  const [timer, setTimer] = useState(0);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [loginError, setLoginError] = useState("");

  const { LogIn, isLoading: isLoggingIn } = useLogin();
  const { mutateAsync: sendOtp, isPending: isSendingOtp } = useSendOtp();
  const { mutateAsync: checkOtp, isPending: isCheckingOtp } = useCheckOtp();
  const { mutateAsync: completeData, isPending: isCompletingData } = useCompleteUserData();

  useEffect(() => {
    let interval;
    if (timer > 0) {
      interval = setInterval(() => {
        setTimer((prev) => prev - 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [timer]);

  // Login Handler
  const handleLogin = async (values) => {
    setLoginError("");
    try {
      await LogIn({ phone_number: values.phone, password: values.password });
    } catch (error) {
      const errorMessages = error?.response?.data?.errors;
      const formattedErrors = Array.isArray(errorMessages)
        ? errorMessages.join(' - ')
        : (errorMessages || 'ورود ناموفق بود. لطفاً شماره موبایل و رمز عبور را بررسی کنید.');
      setLoginError(formattedErrors);
    }
  };

  // Registration Handlers
  const handleSendOtp = async (values) => {
    try {
      await sendOtp({ phone_number: values.phone });
      setPhoneNumber(values.phone);
      setStep(STEPS.OTP);
      setTimer(120);
    } catch (error) {}
  };

  const handleCheckOtp = async (values) => {
    try {
      const res = await checkOtp({ phone_number: phoneNumber, code: values.otp });
      const user = res?.data?.data;
      const token = res?.data?.token;
      
      // If user info is incomplete (name is missing), go to complete data step
      if (user && !user.name) {
        setUserId(user.id);
        setAuthToken(token);
        setStep(STEPS.COMPLETE);
      }
    } catch (error) {}
  };

  const handleCompleteData = async (values) => {
    try {
      await completeData({
        token: authToken,
        user_id: userId,
        name: values.name,
        password: values.password
      });
    } catch (error) {}
  };

  const resendOtp = () => {
    if (timer === 0) {
      handleSendOtp({ phone: phoneNumber });
    }
  };

  // Validation Schemas
  const loginSchema = Yup.object().shape({
    phone: Yup.string()
      .matches(/^09\d{9}$/, "شماره موبایل معتبر نیست")
      .required("شماره موبایل الزامی است"),
    password: Yup.string().required("رمز عبور الزامی است"),
  });

  const phoneSchema = Yup.object().shape({
    phone: Yup.string()
      .matches(/^09\d{9}$/, "شماره موبایل معتبر نیست")
      .required("شماره موبایل الزامی است"),
  });

  const otpSchema = Yup.object().shape({
    otp: Yup.string()
      .matches(/^\d{5}$/, "کد تایید باید ۵ رقم باشد")
      .required("کد تایید الزامی است"),
  });

  const completeSchema = Yup.object().shape({
    name: Yup.string().required("نام و نام خانوادگی الزامی است"),
    password: Yup.string()
      .min(6, "رمز عبور باید حداقل 6 کاراکتر باشد")
      .required("رمز عبور الزامی است"),
    confirmPassword: Yup.string()
      .oneOf([Yup.ref('password'), null], 'تکرار رمز عبور مطابقت ندارد')
      .required('تکرار رمز عبور الزامی است')
  });

  return (
    <>
      <div className="min-h-[calc(100vh-200px)] flex items-center justify-center py-6 sm:py-12 px-3 sm:px-4 bg-gray-50 pb-24">
        <div className="max-w-md w-full mx-auto bg-white rounded-[10px] border border-gray-200 shadow-lg p-6 sm:p-8 md:p-10">
          <div className="text-center mb-8">
            <div className="flex justify-center items-center">
              <img src={logo} alt="اربعین تی وی" className="h-32 sm:h-38 md:h-40 w-auto" />
            </div>
            <h2 className="text-xl font-bold mt-4 text-gray-800">
              {mode === MODES.LOGIN ? '' : 'ثبت‌نام در سامانه'}
            </h2>
          </div>

          {mode === MODES.LOGIN ? (
            /* --- LOGIN FORM --- */
            <Formik
              initialValues={{ phone: "", password: "" }}
              validationSchema={loginSchema}
              onSubmit={handleLogin}
            >
              {({ isSubmitting }) => (
                <Form className="space-y-5">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">شماره موبایل</label>
                    <div className="relative flex items-center gap-3 rounded-[10px] border border-gray-300 bg-gray-50 hover:bg-white hover:border-gray-400 transition-all px-4 py-2">
                      <Sms size={20} color="#64748b" />
                      <Field
                        type="tel"
                        name="phone"
                        className="w-full bg-transparent focus:outline-none focus:ring-0 text-sm placeholder-gray-400"
                        placeholder="0912xxxxxxx"
                      />
                    </div>
                    <ErrorMessage name="phone" component="p" className="text-red-600 text-sm mt-1" />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">رمز عبور</label>
                    <div className="relative flex items-center gap-3 rounded-[10px] border border-gray-300 bg-gray-50 hover:bg-white hover:border-gray-400 transition-all px-4 py-2">
                      <Lock size={20} color="#64748b" />
                      <Field
                        type={showPassword ? "text" : "password"}
                        name="password"
                        className="w-full bg-transparent focus:outline-none focus:ring-0 text-sm placeholder-gray-400"
                        placeholder="••••••••"
                      />
                      <div className="absolute left-4 cursor-pointer" onClick={() => setShowPassword(!showPassword)}>
                        {showPassword ? <Eye size={20} color="#4a5565" /> : <EyeSlash size={20} color="#4a5565" />}
                      </div>
                    </div>
                    <ErrorMessage name="password" component="p" className="text-red-600 text-sm mt-1" />
                  </div>

                  {loginError && <p className="text-red-600 text-sm text-center">{loginError}</p>}

                  <button
                    type="submit"
                    className="w-full py-3 rounded-[10px] bg-gradient-to-r from-orange-400 to-red-400 hover:from-orange-500 hover:to-red-500 active:scale-95 text-white font-medium text-sm shadow-md transition-all"
                    disabled={isSubmitting || isLoggingIn}
                  >
                    {isLoggingIn ? "در حال ورود..." : "ورود"}
                  </button>

                  <div className="text-center pt-4 border-t border-gray-100">
                    <p className="text-sm text-gray-600 mb-2">هنوز حساب کاربری ندارید؟</p>
                    <button
                      type="button"
                      onClick={() => { setMode(MODES.REGISTER); setStep(STEPS.PHONE); }}
                      className="text-orange-500 hover:text-orange-600 font-bold text-sm underline underline-offset-4"
                    >
                      ثبت‌نام در سامانه
                    </button>
                  </div>
                </Form>
              )}
            </Formik>
          ) : (
            /* --- REGISTRATION FLOW (OTP) --- */
            <div className="space-y-5">
              {step === STEPS.PHONE && (
                <Formik
                  initialValues={{ phone: "" }}
                  validationSchema={phoneSchema}
                  onSubmit={handleSendOtp}
                >
                  {({ isSubmitting }) => (
                    <Form className="space-y-5">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">شماره موبایل</label>
                        <div className="relative flex items-center gap-3 rounded-[10px] border border-gray-300 bg-gray-50 hover:bg-white hover:border-gray-400 transition-all px-4 py-2">
                          <Sms size={20} color="#64748b" />
                          <Field
                            type="tel"
                            name="phone"
                            className="w-full bg-transparent focus:outline-none focus:ring-0 text-sm placeholder-gray-400"
                            placeholder="0912xxxxxxx"
                          />
                        </div>
                        <ErrorMessage name="phone" component="p" className="text-red-600 text-sm mt-1" />
                      </div>

                      <button
                        type="submit"
                        className="w-full py-3 rounded-[10px] bg-gradient-to-r from-orange-400 to-red-400 hover:from-orange-500 hover:to-red-500 active:scale-95 text-white font-medium text-sm shadow-md transition-all"
                        disabled={isSubmitting || isSendingOtp}
                      >
                        {isSendingOtp ? "در حال ارسال..." : "ارسال کد تایید"}
                      </button>

                      <div className="text-center pt-4 border-t border-gray-100">
                        <button
                          type="button"
                          onClick={() => setMode(MODES.LOGIN)}
                          className="text-gray-500 hover:text-gray-700 text-sm font-medium"
                        >
                          بازگشت به صفحه ورود
                        </button>
                      </div>
                    </Form>
                  )}
                </Formik>
              )}

              {step === STEPS.OTP && (
                <Formik
                  initialValues={{ otp: "" }}
                  validationSchema={otpSchema}
                  onSubmit={handleCheckOtp}
                >
                  {({ values, setFieldValue, isSubmitting }) => (
                    <Form className="space-y-5">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-3 text-center">
                          کد تایید
                        </label>
                        <OTPInput
                          value={values.otp}
                          onChange={(otp) => setFieldValue("otp", otp)}
                        />
                        <ErrorMessage
                          name="otp"
                          component="p"
                          className="text-red-600 text-sm mt-2 text-center"
                        />
                      </div>

                      <div className="text-center">
                        {timer > 0 ? (
                          <p className="text-sm text-gray-500">
                            ارسال مجدد کد تا {Math.floor(timer / 60)}:{(timer % 60).toString().padStart(2, '0')} دیگر
                          </p>
                        ) : (
                          <button type="button" onClick={resendOtp} className="text-sm text-orange-500 hover:text-orange-600 font-medium">
                            ارسال مجدد کد تایید
                          </button>
                        )}
                      </div>

                      <button
                        type="submit"
                        className="w-full py-3 rounded-[10px] bg-gradient-to-r from-orange-400 to-red-400 hover:from-orange-500 hover:to-red-500 active:scale-95 text-white font-medium text-sm shadow-md transition-all"
                        disabled={isSubmitting || isCheckingOtp}
                      >
                        {isCheckingOtp ? "در حال بررسی..." : "تایید کد"}
                      </button>

                      <button
                        type="button"
                        onClick={() => setStep(STEPS.PHONE)}
                        className="w-full text-sm text-gray-500 hover:text-gray-700"
                      >
