"use client";

import { useCallback, useEffect, useMemo, useState } from "react";


import VideoGrid from "../components/VideoGrid";
import VideoSkeleton from "../components/VideoSkeleton";

const bgImag = "/assets/img/bgImag.jpg";
import useChannelDetail from "../hooks/channel/useChannelDetail";
import { useInfiniteScroll } from "../hooks/ui/useInfiniteScroll";
import { useInfiniteLandingVideos } from "../hooks/video/useInfiniteLandingVideos";
import { EmptyState, ErrorMessage } from "../ui";
import { getSocialIcon } from "../utils/socialIcons";
import { Category } from "iconsax-react";

const PAGE_SIZE = 25;

const ProfileChannel = ({ initialChannelId, initialItems = [], initialGrid }) => {

  const channelId = initialChannelId;
  const [showSocials, setShowSocials] = useState(false);

  // CHANNEL DETAIL
  const {
    data: channelData,
    isLoading: channelLoading,
    refetch: refetchChannel,
  } = useChannelDetail(channelId, { enabled: !!channelId });

  // VIDEOS
  const {
    data: videosData,
    isLoading: videosLoading,
    isError: videosError,
    isFetchingNextPage,
    hasNextPage,
    fetchNextPage,
    refetch: refetchVideos,
  } = useInfiniteLandingVideos(channelId, PAGE_SIZE);

  const loadMoreRef = useInfiniteScroll({
    hasNextPage,
    isFetchingNextPage,
    fetchNextPage,
  });

  // CHANNEL
  const channel = channelData?.data;

  // VIDEOS LIST
  const videosList = useMemo(() => {
    return videosData?.pages?.flatMap((page) => page.items || []) || [];
  }, [videosData]);

  // RETRY
  const handleRefresh = useCallback(() => {
    refetchVideos();
  }, [refetchVideos]);

  const showInitialLoading = videosLoading && videosList.length === 0;
  const socials = channel?.socials
    ? Object.entries(channel.socials).filter(([, social]) => social?.link)
    : [];

  return (
    <>
      <div className="min-h-screen bg-gradient-to-b from-slate-50 to-white">
        <div className="isolate mx-auto max-w-7xl px-3 sm:px-4 md:px-6 py-6 sm:py-8">
