                      {channel?.description && (
                        <p className="text-sm text-gray-600 mt-1 max-w-2xl">
                          {channel.description}
                        </p>
                      )}
                    </div>

                    <div className="flex items-center gap-2 flex-wrap justify-center">
                      {socials.slice(0, 3).map(([key, social]) => {
                        const iconUrl = getSocialIcon(key, social.icon);

                        return (
                          <a
                            key={key}
                            href={social.link}
                            target="_blank"
                            rel="noopener noreferrer"
                            title={key}
                            className="
                  w-10 h-10
                  flex items-center justify-center
                  rounded-full
                  bg-gray-100
                  hover:bg-orange-50
                  hover:scale-110
                  transition-all duration-300
                "
                          >
                            <img
                              src={iconUrl}
                              alt={key}
                              className="w-10 h-10 object-contain"
                            />
                          </a>
                        );
                      })}

                      {socials.length > 3 && (
                        <div className="relative">
                          <button
                            type="button"
                            onClick={() => setShowSocials((prev) => !prev)}
                            className="
                  w-10 h-10
                  flex items-center justify-center
                  rounded-full
                  bg-orange-50
                  hover:bg-orange-100
                  transition-all duration-300
                "
                          >
                            <Category
                              size="20"
                              color="#FF8A65"
                              variant="Bold"
                            />
                          </button>

                          <div
                            className={`
                  absolute top-12 left-1/2 -translate-x-1/2
                  flex items-center gap-2
                  bg-white rounded-xl shadow-lg p-2 z-50
                  transition-all duration-300
                  ${showSocials ? "opacity-100 visible" : "opacity-0 invisible"}
                `}
                          >
                            {socials.slice(3).map(([key, social]) => {
                              const iconUrl = getSocialIcon(key, social.icon);

                              return (
                                <a
                                  key={key}
                                  href={social.link}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  title={key}
                                  className="
                        w-10 h-10
                        flex items-center justify-center
                        rounded-full
                        bg-gray-100
                        hover:bg-orange-50
                        hover:scale-110
                        transition-all duration-300
                      "
                                >
                                  <img
                                    src={iconUrl}
                                    alt={key}
                                    className="w-5 h-5 object-contain"
                                  />
                                </a>
                              );
                            })}
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* VIDEOS */}
          {showInitialLoading ? (
            <div className="mt-6">
              <VideoSkeleton count={PAGE_SIZE} />
            </div>
          ) : videosError ? (
            <ErrorMessage onRetry={handleRefresh} />
          ) : videosList.length === 0 ? (
            <EmptyState
              title="ویدیویی یافت نشد"
              message="در این کانال فعلاً ویدیویی موجود نیست."
            />
          ) : (
            <section>
              <div className="pb-8">
                {initialGrid && JSON.stringify(videosList) === JSON.stringify(initialItems) ? initialGrid : <VideoGrid items={videosList} />}
              </div>

              {/* LOAD MORE */}
              <div
                ref={loadMoreRef}
                className="flex justify-center py-4 min-h-16"
              >
                {isFetchingNextPage ? (
                  <div className="w-full">
                    <VideoSkeleton count={Math.min(8, PAGE_SIZE)} />
                  </div>
                ) : hasNextPage ? (
                  <span className="text-sm text-slate-500">
                    برای بارگذاری ویدیوهای بیشتر اسکرول کنید.
                  </span>
                ) : (
                  <span className="text-sm text-slate-400">
                    همه ویدیوها نمایش داده شدند.
                  </span>
                )}
              </div>
            </section>
          )}
        </div>
      </div>
    </>
  );
};

