  useEffect(() => {
    setTempPath(null);
    setVideoFile(null);
    setVideoStatus("idle");
    setUploadProgress(0);
    setVideoUrl("");
  }, [uploadType]);

  const canEditMetadata = Boolean(videoFile || tempPath);
  const uploadStatusText = useMemo(() => {
    if (uploadType === "url") {
      return videoUrl
        ? "لینک ویدیو وارد شده است."
