  const [thumbnails, setThumbnails] = useState([]);
  const [publicShow, setPublicShow] = useState(1);
  const [videoUrl, setVideoUrl] = useState("");
  const [uploadType, setUploadType] = useState("file"); // 'file' | 'url'
  const navigate = useNavigate();

  const [selectedCategory, setSelectedCategory] = useState("");
  const [selectedPlaylistIds, setSelectedPlaylistIds] = useState([]);

  const [isPlaylistModalOpen, setPlaylistModalOpen] = useState(false);

  const {
    data: categories = [],
    isLoading: isLoadingCategories,
    isError: isCategoriesError,
  } = useCategories({ withPagination: false });
  const {
    data: playlistsResponse,
    isLoading: isLoadingPlaylists,
    isError: isPlaylistsError,
  } = usePlaylists(channelId, {
    enabled: Boolean(channelId),
    withPagination: false,
  });
  const playlists = playlistsResponse?.items || [];

  const createPlaylistMutation = useCreatePlaylist();

  // helper: capture frame from URL
  const captureFrameFromUrl = (videoUrl, timeInSeconds = 0) => {
    return new Promise((resolve, reject) => {
      const video = document.createElement("video");
      video.crossOrigin = "anonymous";
      video.src = videoUrl;
      video.muted = true;
      video.playsInline = true;
      const cleanup = () => {
        try {
          video.src = "";
        } catch (e) {}
      };
      const onError = () => {
        cleanup();
        reject(new Error("video load error / CORS or invalid url"));
      };
      video.addEventListener("loadedmetadata", () => {
        if (!video.duration || isNaN(video.duration)) {
          video.currentTime = 0;
        } else {
          const t = Math.min(timeInSeconds, video.duration);
          video.currentTime = t;
        }
      });
      video.addEventListener("seeked", () => {
        try {
          const w = video.videoWidth || 640;
          const h = video.videoHeight || 360;
          const canvas = document.createElement("canvas");
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(video, 0, 0, w, h);
          canvas.toBlob((blob) => {
            cleanup();
            if (!blob) return reject(new Error("cannot capture frame"));
            resolve(blob);
          }, "image/png");
        } catch (err) {
          cleanup();
          reject(err);
        }
      });
      video.addEventListener("error", onError);
    });
  };

  // wrapper: capture frame from File
  const captureFrameFromFile = async (file, timeInSeconds = 0) => {
    const url = URL.createObjectURL(file);
    try {
      const blob = await captureFrameFromUrl(url, timeInSeconds);
      return blob;
    } finally {
      URL.revokeObjectURL(url);
    }
  };

  // دریافت نتیجه VideoDropzone (مثل Upload)
  const handleVideoUploaded = (payload) => {
    if (!payload) return;
    if (typeof payload === "string") {
      setTempPath(payload);
      setVideoStatus("success");
    } else if (typeof payload === "object") {
      setTempPath(payload.temp_path || null);
      setVideoFile(payload.file || null);
      setVideoStatus("success");
    }
  };

  const handleVideoSelected = (file) => {
    setVideoFile(file || null);
    setTempPath(null);
    setVideoStatus("uploading");

    setVideoUrl("");
  };

  // تولید thumbnails (همان منطق Upload)
  useEffect(() => {
    let canceled = false;
    const createdUrls = [];

    const generate = async () => {
      setThumbnails([]);
      if (!videoFile && !tempPath) return;

      try {
        let duration = 0;
        if (videoFile) {
          const tmp = document.createElement("video");
          const url = URL.createObjectURL(videoFile);
          tmp.src = url;
          await new Promise((res, rej) => {
            tmp.addEventListener("loadedmetadata", res);
            tmp.addEventListener("error", rej);
          });
          duration = tmp.duration || 0;
          URL.revokeObjectURL(url);

          const positions = [0.1, 0.5, 0.9].map((p) =>
            Math.min(duration * p, duration || 0),
          );
          const resArr = [];
          for (const t of positions) {
            try {
              const blob = await captureFrameFromFile(videoFile, t);
              if (canceled) break;
              const u = URL.createObjectURL(blob);
              createdUrls.push(u);
              resArr.push({ time: t, blob, url: u });
            } catch (err) {
              console.warn("capture from file failed", err);
            }
          }
          if (!canceled) setThumbnails(resArr);
        } else if (tempPath) {
          const tmp = document.createElement("video");
          tmp.crossOrigin = "anonymous";
          tmp.src = tempPath;
          await new Promise((res, rej) => {
            tmp.addEventListener("loadedmetadata", res);
            tmp.addEventListener("error", rej);
          });
          duration = tmp.duration || 0;
          const positions = [0.1 * duration, 0.5 * duration, 0.9 * duration];
          const resArr = [];
          for (const t of positions) {
            try {
              const blob = await captureFrameFromUrl(tempPath, t);
              if (canceled) break;
              const u = URL.createObjectURL(blob);
              createdUrls.push(u);
              resArr.push({ time: t, blob, url: u });
            } catch (err) {
              console.warn("capture from url failed", err);
            }
          }
          if (!canceled) setThumbnails(resArr);
        }
      } catch (err) {
        console.warn("thumbnail generation overall error", err);
      }
    };

    generate();

    return () => {
      canceled = true;
      createdUrls.forEach((u) => URL.revokeObjectURL(u));
    };
  }, [videoFile, tempPath]);

  // create/revoke preview URL for thumbnail (existing behavior)
  useEffect(() => {
    if (!thumbFile) {
      if (thumbPreview) {
        try {
          URL.revokeObjectURL(thumbPreview);
        } catch (e) {}
        setThumbPreview(null);
      }
      return;
    }
    if (thumbFile instanceof File || thumbFile instanceof Blob) {
      const u = URL.createObjectURL(thumbFile);
      if (thumbPreview) {
        try {
          URL.revokeObjectURL(thumbPreview);
        } catch (e) {}
      }
      setThumbPreview(u);
    } else {
      if (thumbPreview) {
        try {
          URL.revokeObjectURL(thumbPreview);
        } catch (e) {}
        setThumbPreview(null);
      }
    }
  }, [thumbFile]);

  const uploadStatusText = useMemo(() => {
    if (uploadType === "url") {
      return videoUrl
        ? "لینک ویدیو آماده ثبت است."
        : "لطفاً لینک ویدیو را وارد کنید.";
    }

    if (videoStatus === "success")
      return "آپلود ویدیو کامل شده و آماده انتشار است.";
    if (videoStatus === "uploading") return "آپلود ویدیو در حال انجام است.";
    return "ابتدا فایل ویدیو را انتخاب کنید.";
  }, [videoStatus, uploadType, videoUrl]);

  const resetForm = () => {
    setTitle("");
    setDesc("");
    setThumbFile(null);
    setThumbPreview(null);
    setTempPath(null);
    setVideoFile(null);
    setVideoStatus("idle");
    setThumbnails([]);
    setVideoUrl("");
    setPublicShow(1);
    setSelectedPlaylistIds([]);
  };
  const handleCancelAndRefresh = () => {
    window.location.reload();
  };

  const handleUpload = async () => {
    if (!title || !title.trim()) {
      toast.error("لطفاً عنوان ویدیو را وارد کنید");
      return;
    }

    // 👇 شرط جدید
    if (!tempPath && !videoUrl) {
      toast.error("لطفاً ویدیو آپلود کنید یا لینک وارد کنید");
      return;
    }

    if (!thumbFile) {
      toast.error("لطفاً یک تصویر کاور انتخاب کنید");
      return;
    }

    try {
      await uploadAsync({
        title: title.trim(),
        description: desc,
        temp_path: tempPath,
        url: videoUrl,
        coverFile: thumbFile,
        public_show: publicShow,
        categories: selectedCategory ? [Number(selectedCategory)] : [],
        play_lists: selectedPlaylistIds.map(Number).filter(Number.isFinite),
      });

      navigate("/dashboard/user-videos");
      resetForm();
    } catch {}
  };

  useEffect(() => {
    return () => {
      if (thumbPreview) {
        try {
          URL.revokeObjectURL(thumbPreview);
        } catch (e) {}
      }
      thumbnails.forEach((t) => {
        try {
          URL.revokeObjectURL(t.url);
        } catch (e) {}
      });
    };
  }, []);

  useEffect(() => {
    setTempPath(null);
    setVideoFile(null);
    setVideoStatus("idle");
    setVideoUrl("");
  }, [uploadType]);

  const isFormDisabled = videoStatus !== "success"; // غیرفعال شدن وقتی ویدیو آپلود نشده

  return (
    <UplodLayout>
      <div className="flex justify-center items-center  ">
        <div className="space-y-6 w-full h-full sm:max-w-7xl pb-8 pt-5 px-5">
          <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
            <div className="flex justify-center mb-4">
              <div className="flex bg-gray-100 p-1 rounded-lg">
                {/* <button
                onClick={() => setUploadType("file")}
                className={`px-4 py-2 text-sm rounded-md transition-all ${
                  uploadType === "file"
                    ? "bg-white shadow text-gray-900"
                    : "text-gray-500"
                }`}
              >
                آپلود فایل
              </button> */}

                {/* <button
                onClick={() => setUploadType("url")}
                className={`px-4 py-2 text-sm rounded-md transition-all ${
                  uploadType === "url"
                    ? "bg-white shadow text-gray-900"
                    : "text-gray-500"
                }`}
              >
                لینک ویدیو
              </button> */}
              </div>
            </div>
            {uploadType === "file" ? (
              <VideoDropzone
                onFileSelected={(file) => {
                  handleVideoSelected(file);
                  setVideoUrl("");
                }}
                onUploaded={handleVideoUploaded}
                onProgress={() => {}}
              />
            ) : (
              <div>
                <input
                  value={videoUrl}
                  onChange={(e) => {
                    setVideoUrl(e.target.value);
                    setTempPath(null);
                    setVideoFile(null);
                    setVideoStatus("idle");
                  }}
                  placeholder="https://example.com/video.mp4"
                  className="h-11 px-4 rounded-lg border border-gray-300 w-full focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            )}

            {isFormDisabled && (
              <p className="text-sm mt-4">
                لطفا پیش از بارگذاری ویدیو{" "}
                <span className="text-blue-500">قوانین اربعین تی وی</span> را
                مطالعه کنید
              </p>
            )}
            <div
              className={`rounded-lg border px-3 py-2 mt-3 text-sm ${videoStatus === "success" ? "border-green-200 bg-green-50 text-green-700" : "border-slate-200 bg-slate-50 text-slate-600"}`}
            >
              {uploadStatusText}
              {/* {videoStatus === 'uploading' && uploadProgress > 0 ? ` (${Math.round(uploadProgress)}%)` : ''} */}
            </div>
          </div>
          {videoFile && (
            <div className="flex flex-col gap-4">
              <div className="flex flex-col sm:flex-row gap-2 sm:gap-4 md:gap-6 justify-center sm:justify-between pt-2">
                <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm w-full">
                  {/* FORM */}
                  <div className="space-y-5">
                    {/* TITLE */}
                    <div>
                      <label className="block text-sm font-semibold text-gray-900 mb-2">
                        عنوان ویدیو <span className="text-red-500">*</span>
                      </label>

                      <input
                        value={title}
                        onChange={(e) => setTitle(e.target.value)}
                        placeholder="عنوان ویدیو را وارد کنید"
                        className="h-11 px-4 rounded-lg border border-gray-300 w-full
                   focus:outline-none focus:ring-2 focus:ring-blue-500
                   focus:border-transparent transition-all
                   disabled:bg-gray-100"
                      />
                    </div>

                    {/* DESCRIPTION */}
                    <div>
                      <label className="block text-sm font-semibold text-gray-900 mb-2">
                        توضیحات
                      </label>

                      <textarea
                        value={desc}
                        onChange={(e) => setDesc(e.target.value)}
                        placeholder="توضیحات ویدیو را وارد کنید (اختیاری)"
                        className="h-48 px-4 py-3 rounded-lg border border-gray-300 w-full
                   focus:outline-none focus:ring-2 focus:ring-blue-500
                   focus:border-transparent transition-all resize-none
                   disabled:bg-gray-100"
                      />
                    </div>
                    {/* PUBLIC SWITCH */}
                    <div className="flex items-center justify-between rounded-xl border border-gray-200 bg-white p-3 ">
                      <div className="flex flex-col">
                        <span className="text-sm font-medium text-gray-800">
                          نمایش عمومی ویدیو
                        </span>
                        <span className="text-xs text-gray-500">
                          در صورت فعال بودن، ویدیو برای همه کاربران قابل مشاهده
                          است
                        </span>
                      </div>

                      <label className="relative inline-flex cursor-pointer items-center">
                        <input
                          type="checkbox"
                          checked={publicShow === 1}
                          onChange={(e) =>
                            setPublicShow(e.target.checked ? 1 : 0)
                          }
                          className="sr-only peer"
                        />

                        <div
                          className="
      h-6 w-11 rounded-full bg-gray-300 
      peer-checked:bg-blue-600 
      transition-colors duration-300
      after:content-[''] after:absolute after:top-[2px] after:left-[2px]
      after:h-5 after:w-5 after:rounded-full after:bg-white
      after:transition-all after:duration-300
      peer-checked:after:translate-x-5
      
    "
                        />
                      </label>
                    </div>
                    {/* CATEGORY */}
                    <div>
                      <div className="flex justify-between items-center mb-3">
                        <label className="text-sm font-semibold text-gray-900">
                          دسته‌بندی‌ها
                        </label>
                      </div>

                      {isLoadingCategories ? (
                        <p className="text-sm text-gray-500">
                          در حال بارگذاری...
                        </p>
                      ) : isCategoriesError ? (
                        <p className="text-sm text-red-600">
                          خطا در دریافت دسته‌بندی‌ها
                        </p>
                      ) : (
                        <div className="relative">
                          <select
                            value={selectedCategory || ""}
                            onChange={(e) =>
                              setSelectedCategory(e.target.value)
                            }
                            className="
          w-full h-11
          appearance-none
          bg-transparent
          px-4 pr-10
          text-sm text-gray-700
          rounded-lg
          border border-gray-200
          focus:outline-none focus:ring-2 focus:ring-blue-500
        "
                          >
                            <option value="">انتخاب دسته‌بندی</option>

                            {categories.map((c) => (
                              <option key={c.id} value={c.id}>
                                {c.title || c.name}
                              </option>
                            ))}
                          </select>

                          {/* icon */}
                          <div className="pointer-events-none absolute inset-y-0 right-3 flex items-center text-gray-400">
                            <ArrowDown2 size={14} color="currentColor" />
                          </div>
                        </div>
                      )}
                    </div>

                    {/* PLAYLIST */}
                    <div className="w-full">
                      {/* Header */}
                      <div className="flex justify-between items-center mb-3">
                        <label className="text-sm font-semibold text-gray-900">
                          پلی‌لیست (اختیاری)
                        </label>

                        <button
                          type="button"
                          onClick={() => setPlaylistModalOpen(true)}
                          className="text-xs font-medium text-blue-600 hover:text-blue-700 transition"
                        >
                          + ایجاد پلی‌لیست
                        </button>
                      </div>

                      {/* Body */}
                      <div className="">
                        {/* Loading */}
                        {isLoadingPlaylists ? (
                          <div className="p-3 text-sm text-gray-500">
                            در حال بارگذاری پلی‌لیست‌ها...
                          </div>
                        ) : isPlaylistsError ? (
                          <div className="p-3 text-sm text-red-600">
                            خطا در دریافت پلی‌لیست‌ها
                          </div>
                        ) : playlists.length === 0 ? (
                          <div className="p-3 text-sm text-gray-500">
                            هیچ پلی‌لیستی وجود ندارد.
                          </div>
                        ) : (
                          <MultiSelect
                            options={playlists}
                            value={selectedPlaylistIds}
                            onChange={setSelectedPlaylistIds}
                            placeholder="جستجوی پلی‌لیست..."
                            emptyMessage="پلی‌لیستی وجود ندارد"
                            getOptionLabel={(item) =>
                              item?.name || `پلی‌لیست ${item?.id}`
                            }
                          />
                        )}
                      </div>
                    </div>
                  </div>
                </div>

                <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm w-full ">
                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-semibold text-gray-900 mb-2">
                        تصویر کاور (اجباری)
                      </label>
                      <div>
                        <CoverPicker
                          value={thumbFile}
                          onChange={(file) => setThumbFile(file)}
                          onConfirm={(file) => {
                            setThumbFile(file);
                          }}
                          defaultCovers={[
                            cover,
                            "/covers/default2.jpg",
                            "/covers/default3.jpg",
                          ]}
                          videoFile={videoFile}
                          videoUrl={tempPath}
                          videoThumbnails={thumbnails}
                        />
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex gap-2 justify-end">
                <button
                  onClick={handleCancelAndRefresh}
                  className={`px-6 py-2.5 border border-gray-300 text-gray-700 font-medium rounded-lg hover:bg-gray-50 transition-all duration-200 text-sm flex items-center gap-2 hover:border-red-300 hover:text-red-700 hover:bg-red-50 `}
                >
                  <CloseCircle size={16} color="currentColor" />
                  انصراف
                </button>
                <button
                  onClick={handleUpload}
                  disabled={
                    !title ||
                    (uploadType === "file" && !tempPath) ||
                    (uploadType === "url" && !videoUrl) ||
                    isPending ||
                    !thumbFile
                  }
                  className="   h-12 px-6 rounded-lg
    bg-gradient-to-r from-blue-500 via-blue-600 to-blue-700
    hover:from-blue-600 hover:via-blue-600 hover:to-blue-600
    disabled:from-gray-300 disabled:via-gray-300 disabled:to-gray-300
    disabled:text-gray-500 disabled:shadow-none disabled:cursor-not-allowed
    text-white text-sm font-medium
    transition-all duration-200
    flex items-center justify-center gap-2
    shadow-md hover:shadow-lg
  "
                >
                  {isPending ? (
                    <>در حال آپلود...</>
                  ) : (
                    <>
                      <TickCircle
                        size={20}
                        color={
                          !title.trim() ||
                          (uploadType === "file" && !tempPath) ||
                          (uploadType === "url" && !videoUrl) ||
                          isPending ||
                          !thumbFile
                            ? "#000000"
                            : "#ffffff"
                        }
                      />
                      انتشار ویدیو
                    </>
                  )}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
      <PlaylistModal
        isOpen={isPlaylistModalOpen}
        onClose={() => setPlaylistModalOpen(false)}
        isPending={createPlaylistMutation.isPending}
        onSubmit={async (payload) => {
          await createPlaylistMutation.mutateAsync(payload);
        }}
      />
    </UplodLayout>
  );
}

export default UserVideos;

import axiosInstanceNew from "../utils/axiosConfigNew";
import { getAllPaginatedItems, normalizePage } from "../utils/pagination";

const mapPaginatedResponse = (data) => {
  const items =
    Array.isArray(data?.data) ? data.data :
      Array.isArray(data?.data?.data) ? data.data.data :
        [];

  const totalPages =
    Number(data?.last_page ||
      data?.meta?.last_page ||
      data?.pagination?.last_page ||
      1) || 1;

  const totalItems =
    Number(data?.total ||
      data?.meta?.total ||
      items.length) || items.length;

  return { items, totalPages, totalItems };
};

const buildVideoListParams = ({ page = 1, per_page = 25, video_type = "all" } = {}) => {
  const params = {
    page,
    per_page,
  };

  if (video_type) {
    params.video_type = video_type;
  }

  return params;
};

const appendArrayField = (formData, fieldName, values = []) => {
  if (!Array.isArray(values)) return;

  values
    .filter((value) => value !== "" && value !== null && typeof value !== "undefined")
    .forEach((value) => {
      formData.append(fieldName, value);
    });
};

export const getVideoPlaylistIds = (video = {}) => {
  const rawSources = [
    video?.play_lists,
    video?.playlists,
    video?.playlist_ids,
    video?.play_list_ids,
    video?.data?.play_lists,
    video?.data?.playlists,
  ];

  for (const source of rawSources) {
    if (!Array.isArray(source)) continue;

    return source
      .map((item) => (typeof item === "object" ? item?.id ?? item?.playlist_id : item))
      .filter((item) => item !== null && typeof item !== "undefined" && item !== "")
      .map((item) => Number(item))
      .filter((item) => Number.isFinite(item));
  }

  return [];
};

export const uploadVideo = async (file) => {
  const fd = new FormData();
  fd.append("file", file);

  const res = await axiosInstanceNew.post("/video/upload", fd, {
    headers: { "Content-Type": "multipart/form-data" }
  });

  return res.data;
};

// ذخیره ویدیو
export const storeVideo = async (
  channelId,
  { path, url, title, description, cover, public_show, categories = [], play_lists = [] }
) => {
  const fd = new FormData();

  // یکی از این دو باید ارسال بشه
  if (path) fd.append("path", path);
  if (url) fd.append("url", url);

  fd.append("title", title);
  fd.append("description", description || "");

  // public_show (0 یا 1)
  fd.append("public_show", public_show ? 1 : 0);

  if (cover) fd.append("cover", cover);
  appendArrayField(fd, "categories[]", categories);
  appendArrayField(fd, "play_lists[]", play_lists);

  const finalUrl = channelId
    ? `/video/store-video/${channelId}`
    : "/video/store-video";

  const res = await axiosInstanceNew.post(finalUrl, fd, {
    headers: { "Content-Type": "multipart/form-data" },
  });

  return res.data;
};

export const getVideosByChannel = async (
  channelId,
  page = 1,
  per_page = 25,
  video_type = "all",
) => {
  const res = await axiosInstanceNew.get(`/video/${channelId}`, {
    params: buildVideoListParams({ page, per_page, video_type }),
  });
  return mapPaginatedResponse(res.data);
};

export const getVideoDetail = async (id) => {
  const res = await axiosInstanceNew.get(`/video/show/${id}`);
  return res.data;
};

export const getAllVideos = async (page = 1, per_page = 25, video_type = "all") => {
  const res = await axiosInstanceNew.get("/video", {
    params: buildVideoListParams({ page, per_page, video_type }),
  });
  return mapPaginatedResponse(res.data);
};

export const getLandingChannels = async (page = 1) => {
  const res = await axiosInstanceNew.get('/landing/channels', {
    params: { page: normalizePage(page) },
  });
  return mapPaginatedResponse(res.data);
};

export const getAllLandingChannels = () => getAllPaginatedItems(getLandingChannels);

export const getLandingVideos = async ({
  channelId,
  pageNumber = 1,
  pageSize = 25
} = {}) => {
  const params = new URLSearchParams({
    page: pageNumber,
    per_page: pageSize,
  });

  if (channelId) {
    params.append('channel_id', channelId);
  }

  const url = `/landing/videos?${params}`;
  const res = await axiosInstanceNew.get(url);

  // استفاده از mapPaginatedResponse موجود
  return mapPaginatedResponse(res.data);
};

export const getSearch = async (q) => {
  const res = await axiosInstanceNew.get(`/search/${encodeURIComponent(q)}`);
  return res.data;
};

export const deleteVideo = async (id) => {
  const res = await axiosInstanceNew.delete(`/video/delete/${id}`);
  return res.data;
};

export const updateVideo = async (
  videoId,
  { title, description, coverFile, public_show, play_lists = [] },
) => {
  const fd = new FormData();
  fd.append("title", title || "");
  fd.append("description", description || "");
  fd.append("public_show", public_show ?? 1);
  appendArrayField(fd, "play_lists[]", play_lists);


  if (coverFile) {
    fd.append("cover", coverFile);
  }

  const res = await axiosInstanceNew.post(`/video/update-video/${videoId}`, fd, {
    headers: { "Content-Type": "multipart/form-data" },
  });

  return res.data;
};

export default {
  uploadVideo,
  storeVideo,
  getVideosByChannel,
  getVideoDetail,
  getAllVideos,
  // getLanding,
  getSearch,
  deleteVideo,
  updateVideo,
  getLandingVideos,
  getLandingChannels,
  getAllLandingChannels
};
